import{_ as a,o as h,c as t,a2 as i}from"./chunks/framework.O93z6AWZ.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Học Máy trong Y Tế & Chăm Sóc Sức Khỏe","actions":[{"theme":"brand","text":"🚀 Bắt đầu đọc Bài giảng","link":"/ch01_gioi_thieu_hoc_may_y_te"},{"theme":"alt","text":"📋 Đề cương chi tiết (CLO/PLO)","link":"/syllabus"}]},"features":[{"icon":"🎯","title":"Khung Sư Phạm 16 Mục Chuẩn v5","details":"Mỗi chương được thiết kế toàn diện từ Chuẩn đầu ra Bloom (CLO), Box lâm sàng, Box cảnh báo an toàn y khoa đến 40 câu hỏi trắc nghiệm & tự luận."},{"icon":"🔬","title":"8 Bài Toán Lâm Sàng Thực Tế","details":"Đi từ chẩn đoán rối loạn nhịp tim ECG (MIT-BIH), tiền xử lý hồ sơ bệnh án EHR (MIMIC-IV), giải mã vi mảng gen p >> n đến phân loại tổn thương X-quang phổi và Grad-CAM."},{"icon":"🔒","title":"Khóa Trích Dẫn Đóng BibTeX","details":"Hơn 320 lượt trích dẫn học thuật khép kín với 58 nguồn tài liệu tham khảo quốc tế (Bishop, Hastie, Géron, MIT Critical Data, Nature Medicine, Lancet Digital Health)."},{"icon":"💻","title":"Kho Code Lab Thực Hành Độc Lập","details":"8 bộ mã nguồn Python thực chiến đã kiểm thử 100% thành công, tích hợp kiểm soát rò rỉ dữ liệu bệnh nhân (Patient-level split) và đánh giá chi phí sai lầm y tế."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),e={name:"index.md"};function c(s,n,o,r,p,l){return h(),t("div",null,[...n[0]||(n[0]=[i('<h2 id="📚-danh-muc-8-chuong-bai-giang-hoc-phan-et4248" tabindex="-1">📚 Danh Mục 8 Chương Bài Giảng (Học Phần ET4248) <a class="header-anchor" href="#📚-danh-muc-8-chuong-bai-giang-hoc-phan-et4248" aria-label="Permalink to &quot;📚 Danh Mục 8 Chương Bài Giảng (Học Phần ET4248)&quot;">​</a></h2><div class="chapter-grid"><a href="/hmyt-book/ch01_gioi_thieu_hoc_may_y_te" class="chapter-card"><div><span class="badge-archetype badge-a">Archetype A</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 01</span></div><h3>Chương 1: Giới Thiệu Chung Về Học Máy Trong Y Tế</h3><p>Tổng quan hệ sinh thái AI y tế, thách thức 4Vs của dữ liệu y sinh số hóa, quy trình chuẩn hóa từ nghiên cứu đến triển khai lâm sàng và khung pháp lý.</p><div class="meta"><span>🩺 ECG, EHR &amp; Phân loại lâm sàng</span></div></a><a href="/hmyt-book/ch02_kham_pha_va_tien_xu_ly_du_lieu_y_te" class="chapter-card"><div><span class="badge-archetype badge-c">Archetype C</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 02</span></div><h3>Chương 2: Khám Phá Và Tiền Xử Lý Dữ Liệu Y Tế</h3><p>Chiến lược làm sạch dữ liệu bảng EHR, xử lý dữ liệu khuyết thiếu (MCAR/MAR/MNAR), co giãn đặc trưng và mã hóa dữ liệu xét nghiệm y khoa.</p><div class="meta"><span>🔬 KNNImputer &amp; RobustScaler</span></div></a><a href="/hmyt-book/ch03_mo_hinh_tuyen_tinh_hoi_quy_phan_loai_odds_ratio" class="chapter-card"><div><span class="badge-archetype badge-c">Archetype C</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 03</span></div><h3>Chương 3: Mô Hình Tuyến Tính: Hồi Quy, Phân Loại Và Odds Ratio</h3><p>Hồi quy tuyến tính, hồi quy Logistic, giải thích y khoa định lượng với tỷ số chênh Odds Ratio (OR) và phân tích nguy cơ lâm sàng.</p><div class="meta"><span>📊 Odds Ratio &amp; Logistic Regression</span></div></a><a href="/hmyt-book/ch04_chinh_quy_hoa_kiem_chung_va_danh_gia_mo_hinh" class="chapter-card"><div><span class="badge-archetype badge-d">Archetype D</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 04</span></div><h3>Chương 4: Chính Quy Hóa, Kiểm Chứng Và Đánh Giá Mô Hình</h3><p>Kỹ thuật L1/L2 (Lasso/Ridge/ElasticNet) trên dữ liệu p &gt;&gt; n, ma trận nhầm lẫn y khoa (Sensitivity/Specificity), đường cong ROC-AUC và Precision-Recall.</p><div class="meta"><span>🎯 Nested CV &amp; ROC-AUC y khoa</span></div></a><a href="/hmyt-book/ch05_mo_hinh_phi_tuyen_svm_va_lua_chon_dac_trung" class="chapter-card"><div><span class="badge-archetype badge-c">Archetype C</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 05</span></div><h3>Chương 5: Mô Hình Phi Tuyến, SVM Và Lựa Chọn Đặc Trưng</h3><p>Máy vector hỗ trợ (SVM), mẹo hàm nhân (Kernel Trick), cây quyết định và thuật toán loại trừ đặc trưng đệ quy (RFE) trong chẩn đoán ung thư.</p><div class="meta"><span>🧬 Kernel SVM &amp; RFE Feature Selection</span></div></a><a href="/hmyt-book/ch06_hoc_khong_giam_sat_va_giam_chieu_du_lieu" class="chapter-card"><div><span class="badge-archetype badge-c">Archetype C</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 06</span></div><h3>Chương 6: Học Không Giám Sát Và Giảm Chiều Dữ Liệu</h3><p>Phân cụm kiểu hình lâm sàng (K-Means, GMM), nén chiều dữ liệu PCA/t-SNE/UMAP và tách tín hiệu y sinh mù (Blind Source Separation với FastICA).</p><div class="meta"><span>📉 PCA, UMAP &amp; FastICA Tín hiệu</span></div></a><a href="/hmyt-book/ch07_mang_no_ron_nhan_tao_toi_uu_hoa" class="chapter-card"><div><span class="badge-archetype badge-d">Archetype D</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 07</span></div><h3>Chương 7: Mạng Nơ-ron Nhân Tạo: Tối Ưu Hóa Và Tinh Chỉnh Siêu Tham Số</h3><p>Kiến trúc Multi-layer Perceptron (MLP), thuật toán lan truyền ngược, các hàm kích hoạt (ReLU/GELU), chiến lược chống quá khớp Dropout và Batch Normalization.</p><div class="meta"><span>🧠 Deep MLP &amp; Adam Optimization</span></div></a><a href="/hmyt-book/ch08_mang_no_ron_tich_chap_cnn_anh_y_te" class="chapter-card"><div><span class="badge-archetype badge-e">Archetype E</span><span style="font-size:0.8rem;color:var(--vp-c-text-3);">Chương 08</span></div><h3>Chương 8: Mạng Nơ-ron Tích Chập (CNN) Và Ứng Dụng Trong Hình Ảnh Y Tế</h3><p>Các khối tích chập 2D/3D, kiến trúc kinh điển ResNet/DenseNet, học chuyển giao (Transfer Learning) và giải thích quyết định AI hình ảnh qua Grad-CAM.</p><div class="meta"><span>🩻 ResNet, Transfer Learning &amp; Grad-CAM</span></div></a></div>',2)])])}const _=a(e,[["render",c]]);export{g as __pageData,_ as default};
